-- Phase 31: the invoice becomes the whole IRD document (SPEC core 10).
-- invoices gains the seller as it was at issue (name, address, phone, PAN, VAT registration), the
-- buyer's name, the payment method, the VAT split (taxable, rate, VAT, exempt), who charged the
-- delivery, the amount in words, and line_items: a jsonb copy of the lines as sold.
-- Two CHECKs tie the split to the total: a seller that is not VAT registered has no taxable
-- amount and no VAT, and grand_total = taxable + VAT + exempt (+ a platform delivery charge).
--
-- The columns are NOT NULL without a default: the table must be empty. It is: nothing issued an
-- invoice before this migration (generateFiscalInvoice was not wired), and the table refuses the
-- UPDATE a backfill would need. Generated by drizzle-kit; the ledger_account_type line it also
-- produced was moved to 0032, where it belongs.
ALTER TABLE "invoices" ADD COLUMN "seller_name" text NOT NULL;--> statement-breakpoint
ALTER TABLE "invoices" ADD COLUMN "seller_address" text NOT NULL;--> statement-breakpoint
ALTER TABLE "invoices" ADD COLUMN "seller_phone" text NOT NULL;--> statement-breakpoint
ALTER TABLE "invoices" ADD COLUMN "seller_tax_id" text NOT NULL;--> statement-breakpoint
ALTER TABLE "invoices" ADD COLUMN "seller_is_vat_registered" boolean NOT NULL;--> statement-breakpoint
ALTER TABLE "invoices" ADD COLUMN "buyer_name" text NOT NULL;--> statement-breakpoint
ALTER TABLE "invoices" ADD COLUMN "payment_method" "payment_method" NOT NULL;--> statement-breakpoint
ALTER TABLE "invoices" ADD COLUMN "taxable_amount_npr" numeric(12, 2) NOT NULL;--> statement-breakpoint
ALTER TABLE "invoices" ADD COLUMN "vat_rate_percent" numeric(12, 2) NOT NULL;--> statement-breakpoint
ALTER TABLE "invoices" ADD COLUMN "vat_amount_npr" numeric(12, 2) NOT NULL;--> statement-breakpoint
ALTER TABLE "invoices" ADD COLUMN "exempt_amount_npr" numeric(12, 2) NOT NULL;--> statement-breakpoint
ALTER TABLE "invoices" ADD COLUMN "delivery_charged_by" text NOT NULL;--> statement-breakpoint
ALTER TABLE "invoices" ADD COLUMN "amount_in_words" text NOT NULL;--> statement-breakpoint
ALTER TABLE "invoices" ADD COLUMN "line_items" jsonb NOT NULL;--> statement-breakpoint
ALTER TABLE "invoices" ADD CONSTRAINT "invoices_seller_tax_id_check" CHECK ("invoices"."seller_tax_id" ~ '^[0-9]{9}$');--> statement-breakpoint
ALTER TABLE "invoices" ADD CONSTRAINT "invoices_header_text_check" CHECK (btrim("invoices"."seller_name") <> '' AND btrim("invoices"."seller_address") <> ''
            AND btrim("invoices"."seller_phone") <> '' AND btrim("invoices"."buyer_name") <> ''
            AND btrim("invoices"."amount_in_words") <> '');--> statement-breakpoint
ALTER TABLE "invoices" ADD CONSTRAINT "invoices_delivery_charged_by_check" CHECK ("invoices"."delivery_charged_by" IN ('VENDOR', 'PLATFORM'));--> statement-breakpoint
ALTER TABLE "invoices" ADD CONSTRAINT "invoices_line_items_check" CHECK (jsonb_typeof("invoices"."line_items") = 'array' AND jsonb_array_length("invoices"."line_items") >= 1);--> statement-breakpoint
ALTER TABLE "invoices" ADD CONSTRAINT "invoices_vat_amounts_check" CHECK ("invoices"."taxable_amount_npr" >= 0 AND "invoices"."vat_amount_npr" >= 0 AND "invoices"."exempt_amount_npr" >= 0
            AND "invoices"."vat_rate_percent" IN (0, 13)
            AND ("invoices"."seller_is_vat_registered"
              OR ("invoices"."vat_amount_npr" = 0 AND "invoices"."taxable_amount_npr" = 0 AND "invoices"."vat_rate_percent" = 0)));--> statement-breakpoint
ALTER TABLE "invoices" ADD CONSTRAINT "invoices_vat_split_total_check" CHECK ("invoices"."grand_total_npr" = "invoices"."taxable_amount_npr" + "invoices"."vat_amount_npr" + "invoices"."exempt_amount_npr"
            + CASE WHEN "invoices"."delivery_charged_by" = 'PLATFORM' THEN "invoices"."delivery_charge_npr" ELSE 0 END);